/** 返回一枚 Material Symbols 图标的 inline SVG。 */
export function icon(name, opts = {}) {
  const entry = iconPaths[name] || iconPaths.circle;
  const paths = opts.fill ? entry.f : entry.o;
  const size = opts.size || 24;
  const cls = opts.cls ? ` ${opts.cls}` : '';
  const slot = opts.slot ? ` slot="${opts.slot}"` : '';
  return `<svg class="icon${cls}"${slot} viewBox="0 -960 960 960" width="${size}" height="${size}" aria-hidden="true" focusable="false">${paths
    .map((d) => `<path d="${d}"/>`)
    .join('')}</svg>`;
}

/** 品牌兔标：深色圆角方块 + 白色兔子剪影，两套主题下都成立。 */
export function mark(size = 32, cls = '') {
  const extra = cls ? ` ${cls}` : '';
  return `<svg class="mark${extra}" viewBox="0 0 64 64" width="${size}" height="${size}" aria-hidden="true" focusable="false">
    <rect x="1" y="1" width="62" height="62" rx="19" fill="#17151c"/>
    <rect x="1" y="1" width="62" height="62" rx="19" fill="none" stroke="#ffffff" stroke-opacity=".16" stroke-width="1.5"/>
    <g fill="#ffffff">
      <ellipse cx="24" cy="25.5" rx="5.1" ry="14.6" transform="rotate(-10 24 25.5)"/>
      <ellipse cx="40" cy="25.5" rx="5.1" ry="14.6" transform="rotate(10 40 25.5)"/>
      <circle cx="32" cy="42.5" r="13.6"/>
    </g>
    <g fill="#17151c">
      <ellipse cx="27" cy="41.5" rx="2" ry="3.1"/>
      <ellipse cx="37" cy="41.5" rx="2" ry="3.1"/>
      <ellipse cx="32" cy="47.6" rx="2.7" ry="1.6"/>
    </g>
  </svg>`;
}
